/**
 * Tự động nạp mô hình 3D cổ vật (coc_bach_ang_nam_1288.glb)
 * Tương thích 100% khi chạy trực tiếp qua giao thức file:// chống lỗi CORS
 */
(function() {
    try {
        var b64Data = "";
        var sliceSize = 32768;
        var byteArrays = [];
        for (var offset = 0; offset < b64Data.length; offset += sliceSize) {
            var slice = b64Data.slice(offset, offset + sliceSize);
            var byteChars = atob(slice);
            var bytes = new Uint8Array(byteChars.length);
            for (var i = 0; i < byteChars.length; i++) {
                bytes[i] = byteChars.charCodeAt(i);
            }
            byteArrays.push(bytes);
        }
        var blob = new Blob(byteArrays, { type: 'model/gltf-binary' });
        window.__MODEL_COC_BACH_DANG_BLOB_URL = URL.createObjectURL(blob);
        b64Data = null;
        byteArrays = null;
        console.log("3D Model 2 loaded successfully via Blob:", window.__MODEL_COC_BACH_DANG_BLOB_URL);
        if (typeof window.onModel3DReady === 'function') {
            window.onModel3DReady(2, window.__MODEL_COC_BACH_DANG_BLOB_URL);
        }
    } catch (err) {
        console.error("Lỗi khởi tạo mô hình 3D 2:", err);
    }
})();
